<template>
  <main class="hh-page establishments-page">
    <router-link to="/referencias" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a referencias</router-link>
    <section class="establishment-hero">
      <div><span>RED DE PRESTADORES</span><h1>Establecimientos de salud</h1><p>Administre las instituciones externas que remiten pacientes a la IPS.</p></div>
      <button class="btn btn-light text-primary" @click="openCreate"><i class="ph ph-plus me-1"></i>Nuevo establecimiento</button>
    </section>

    <b-card no-body class="filters-card mt-4"><b-card-body><form class="row g-3" @submit.prevent="searchFirstPage">
      <div class="col-md-5"><label class="form-label">Nombre o código</label><div class="input-icon"><i class="ph ph-magnifying-glass"></i><input v-model.trim="filters.buscar" class="form-control" placeholder="Buscar establecimiento"></div></div>
      <div class="col-md-3"><label class="form-label">Nivel de atención</label><select v-model="filters.nivel_atencion_id" class="form-select"><option value="">Todos</option><option v-for="item in levels" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div>
      <div class="col-md-3"><label class="form-label">Tipo</label><select v-model="filters.tipo_establecimiento_id" class="form-select"><option value="">Todos</option><option v-for="item in types" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div>
      <div class="col-md-1"><label class="form-label">Estado</label><select v-model="filters.activo" class="form-select"><option value="">Todos</option><option value="true">Activo</option><option value="false">Inactivo</option></select></div>
      <div class="col-12 d-flex justify-content-end gap-2"><button type="button" class="btn btn-outline-secondary" @click="clearFilters">Limpiar</button><button class="btn btn-primary px-4" :disabled="loading"><span v-if="loading" class="spinner-border spinner-border-sm me-2"></span>Buscar</button></div>
    </form></b-card-body></b-card>

    <div v-if="notice.text" class="alert mt-3" :class="`alert-${notice.type}`">{{ notice.text }}</div>
    <b-card no-body class="results-card mt-4">
      <b-card-header><div><small>DIRECTORIO INSTITUCIONAL</small><h4 class="mb-0">Establecimientos registrados</h4></div><span>{{ meta.total }} registros</span></b-card-header>
      <div v-if="loading" class="loading-state"><span class="spinner-border text-primary"></span><p>Consultando establecimientos…</p></div>
      <div v-else-if="!items.length" class="empty"><i class="ph ph-buildings"></i><h3>Sin establecimientos</h3><p>No se encontraron instituciones con los filtros seleccionados.</p></div>
      <div v-else class="establishment-grid"><article v-for="item in items" :key="item.id" :class="{ inactive: !item.activo }">
        <header><span class="institution-icon"><i class="ph ph-hospital"></i></span><div><small>{{ item.codigo }}</small><h3>{{ item.nombre }}</h3><p>{{ item.nombre_corto || item.tipo_establecimiento?.nombre || 'Institución de salud' }}</p></div><span class="state" :class="item.activo ? 'active' : 'inactive'"><i class="ph ph-circle-fill"></i>{{ item.activo ? 'Activo' : 'Inactivo' }}</span></header>
        <div class="institution-info"><span><i class="ph ph-map-pin"></i><div><small>Dirección</small><strong>{{ item.direccion || 'No informada' }}</strong></div></span><span><i class="ph ph-phone"></i><div><small>Contacto</small><strong>{{ item.telefono || 'No informado' }}</strong></div></span><span><i class="ph ph-stairs"></i><div><small>Nivel</small><strong>{{ item.nivel_atencion?.nombre || 'No informado' }}</strong></div></span><span><i class="ph ph-bed"></i><div><small>Capacidad</small><strong>{{ item.capacidad_camas ?? '—' }} camas</strong></div></span></div>
        <footer><button class="btn btn-sm btn-outline-primary" @click="openDetail(item)"><i class="ph ph-eye me-1"></i>Ver detalle</button><button class="btn btn-sm btn-outline-secondary" @click="openEdit(item)"><i class="ph ph-pencil-simple me-1"></i>Editar</button><button class="btn btn-sm" :class="item.activo ? 'btn-outline-danger' : 'btn-outline-success'" @click="askToggle(item)">{{ item.activo ? 'Desactivar' : 'Activar' }}</button></footer>
      </article></div>
      <footer v-if="meta.lastPage > 1" class="pagination-bar"><button class="btn btn-sm btn-outline-primary" :disabled="meta.page <= 1 || loading" @click="goPage(meta.page - 1)"><i class="ph ph-caret-left"></i></button><span>Página <strong>{{ meta.page }}</strong> de {{ meta.lastPage }}</span><button class="btn btn-sm btn-outline-primary" :disabled="meta.page >= meta.lastPage || loading" @click="goPage(meta.page + 1)"><i class="ph ph-caret-right"></i></button></footer>
    </b-card>

    <Teleport to="body"><div v-if="formModal" class="modal-layer" @mousedown.self="closeForm"><section class="institution-modal" role="dialog" aria-modal="true"><header><div><small>RED DE PRESTADORES</small><h2>{{ editingId ? 'Editar establecimiento' : 'Nuevo establecimiento' }}</h2></div><button class="btn-close" :disabled="saving" @click="closeForm"></button></header><form @submit.prevent="save"><div class="modal-body"><div v-if="formError" class="alert alert-danger">{{ formError }}</div><div class="row g-3"><div class="col-md-4"><label class="form-label">Código *</label><input v-model.trim="form.codigo" class="form-control" :disabled="Boolean(editingId)" required></div><div class="col-md-8"><label class="form-label">Nombre *</label><input v-model.trim="form.nombre" class="form-control" required></div><div class="col-md-4"><label class="form-label">Nombre corto</label><input v-model.trim="form.nombre_corto" class="form-control"></div><div class="col-md-4"><label class="form-label">Nivel de atención *</label><select v-model="form.nivel_atencion_id" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in levels" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-4"><label class="form-label">Tipo *</label><select v-model="form.tipo_establecimiento_id" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in types" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-8"><label class="form-label">Dirección *</label><input v-model.trim="form.direccion" class="form-control" required></div><div class="col-md-4"><label class="form-label">Teléfono *</label><input v-model.trim="form.telefono" class="form-control" required></div><div class="col-md-6"><label class="form-label">Correo</label><input v-model.trim="form.email" type="email" class="form-control"></div><div class="col-md-3"><label class="form-label">Capacidad de camas</label><input v-model.number="form.capacidad_camas" type="number" min="0" class="form-control"></div><div class="col-md-3"><label class="form-label">Ubicación GPS</label><input v-model.trim="form.ubicacion_gps" class="form-control" placeholder="lat,lng"></div><div class="col-md-6"><label class="form-label">Horario de atención</label><input v-model.trim="form.horario_atencion" class="form-control" placeholder="Ej. 24 horas"></div><div class="col-md-6"><label class="form-label">Servicios disponibles</label><input v-model.trim="servicesText" class="form-control" placeholder="Urgencias, UCI, Cirugía"></div></div><h3 class="section-title">Coordinación institucional</h3><div class="row g-3"><div class="col-md-4"><label class="form-label">Nombre</label><input v-model.trim="form.coordinador_nombre" class="form-control"></div><div class="col-md-4"><label class="form-label">Teléfono</label><input v-model.trim="form.coordinador_telefono" class="form-control"></div><div class="col-md-4"><label class="form-label">Correo</label><input v-model.trim="form.coordinador_email" type="email" class="form-control"></div><div class="col-12"><label class="form-label">Observaciones</label><textarea v-model.trim="form.observaciones" rows="2" maxlength="1000" class="form-control"></textarea></div></div></div><footer><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="closeForm">Cancelar</button><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Guardar establecimiento</button></footer></form></section></div></Teleport>

    <Teleport to="body"><div v-if="detailModal" class="modal-layer" @mousedown.self="detailModal = false"><section class="detail-modal"><header><div><small>DETALLE INSTITUCIONAL</small><h2>{{ selected?.nombre }}</h2><p>{{ selected?.codigo }} · {{ selected?.tipo_establecimiento?.nombre }}</p></div><button class="btn-close" @click="detailModal = false"></button></header><div class="modal-body"><div v-if="detailLoading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><template v-else><div class="detail-summary"><article><small>Total referencias</small><strong>{{ statistics.total_referencias ?? statistics.total_referencias_enviadas ?? 0 }}</strong></article><article><small>Teléfono</small><strong>{{ contact.telefono || selected?.telefono || '—' }}</strong></article><article><small>Correo</small><strong>{{ contact.email || selected?.email || '—' }}</strong></article></div><section class="contact-card"><span><i class="ph ph-user-circle"></i></span><div><small>COORDINADOR</small><strong>{{ contact.coordinador || selected?.coordinador_nombre || 'No informado' }}</strong><p>{{ contact.coordinador_telefono || selected?.coordinador_telefono }} · {{ contact.coordinador_email || selected?.coordinador_email }}</p></div></section><h3 class="section-title">Referencias por estado</h3><div class="stat-list"><article v-for="row in statistics.referencias_por_estado || []" :key="row.estado"><span :style="{ background: row.color }"></span><strong>{{ row.estado }}</strong><em>{{ row.total }}</em></article></div><div v-if="!(statistics.referencias_por_estado || []).length" class="text-muted small">Sin estadísticas detalladas disponibles.</div></template></div><footer><button class="btn btn-outline-secondary" @click="detailModal = false">Cerrar</button><button class="btn btn-primary" @click="detailModal = false; openEdit(selected)"><i class="ph ph-pencil-simple me-1"></i>Editar</button></footer></section></div></Teleport>

    <Teleport to="body"><div v-if="toggleTarget" class="confirm-layer" @mousedown.self="toggleTarget = null"><section><span :class="toggleTarget.activo ? 'danger' : 'success'"><i :class="toggleTarget.activo ? 'ph ph-pause-circle' : 'ph ph-check-circle'"></i></span><h3>¿{{ toggleTarget.activo ? 'Desactivar' : 'Activar' }} establecimiento?</h3><p><strong>{{ toggleTarget.nombre }}</strong> {{ toggleTarget.activo ? 'dejará de aparecer entre las instituciones disponibles para nuevas referencias.' : 'volverá a estar disponible para nuevas referencias.' }}</p><div><button class="btn btn-outline-secondary" :disabled="saving" @click="toggleTarget = null">Cancelar</button><button class="btn" :class="toggleTarget.activo ? 'btn-danger' : 'btn-success'" :disabled="saving" @click="toggleStatus"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Confirmar</button></div></section></div></Teleport>
  </main>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { obtenerMensajeError } from '@/services/api'
import { actualizarEstablecimiento, cambiarEstadoEstablecimiento, consultarContactoEstablecimiento, consultarEstablecimiento, consultarEstadisticasEstablecimiento, crearEstablecimiento, listarEstablecimientos, listarNivelesAtencion, listarTiposEstablecimiento } from '@/services/referencias'

const items=ref([]),levels=ref([]),types=ref([]),loading=ref(false),saving=ref(false),formModal=ref(false),detailModal=ref(false),detailLoading=ref(false),editingId=ref(null),selected=ref(null),toggleTarget=ref(null),formError=ref(''),servicesText=ref(''),statistics=ref({}),contact=ref({})
const notice=reactive({text:'',type:'success'}),filters=reactive({buscar:'',nivel_atencion_id:'',tipo_establecimiento_id:'',activo:''}),meta=reactive({page:1,lastPage:1,total:0,perPage:15})
const emptyForm=()=>({codigo:'',nombre:'',nombre_corto:'',nivel_atencion_id:'',tipo_establecimiento_id:'',direccion:'',telefono:'',email:'',capacidad_camas:null,horario_atencion:'',coordinador_nombre:'',coordinador_telefono:'',coordinador_email:'',ubicacion_gps:'',observaciones:'',activo:true}),form=reactive(emptyForm())
const array=value=>Array.isArray(value)?value:Array.isArray(value?.data)?value.data:[],id=item=>item.id??item.nivel_atencion_id??item.tipo_establecimiento_id,name=item=>item.nombre??item.name??item.descripcion
function normalizeList(response){const root=response?.data??response;if(Array.isArray(root))return{rows:root,page:1,lastPage:1,total:root.length,perPage:root.length};const rows=Array.isArray(root?.data)?root.data:[];return{rows,page:Number(root?.current_page||1),lastPage:Number(root?.last_page||1),total:Number(root?.total??rows.length),perPage:Number(root?.per_page||15)}}
async function load(page=meta.page){loading.value=true;notice.text='';try{const result=normalizeList(await listarEstablecimientos({...filters,per_page:meta.perPage,page}));items.value=result.rows;Object.assign(meta,result)}catch(error){showError(error)}finally{loading.value=false}}
function searchFirstPage(){load(1)}function goPage(page){load(page)}function clearFilters(){Object.keys(filters).forEach(key=>filters[key]='');load(1)}
function openCreate(){editingId.value=null;Object.assign(form,emptyForm());servicesText.value='';formError.value='';formModal.value=true}
async function openEdit(item){editingId.value=item.id;formError.value='';try{const response=await consultarEstablecimiento(item.id);const value=response?.data||response||item;Object.assign(form,emptyForm(),value,{nivel_atencion_id:value.nivel_atencion_id??value.nivel_atencion?.id,tipo_establecimiento_id:value.tipo_establecimiento_id??value.tipo_establecimiento?.id});servicesText.value=Array.isArray(value.servicios_json)?value.servicios_json.join(', '):'';formModal.value=true}catch(error){showError(error)}}
function clean(payload){return Object.fromEntries(Object.entries(payload).filter(([,value])=>value!==''&&value!==null&&value!==undefined))}
function closeForm(){if(!saving.value)formModal.value=false}
async function save(){saving.value=true;formError.value='';try{const payload=clean({...form,nivel_atencion_id:Number(form.nivel_atencion_id),tipo_establecimiento_id:Number(form.tipo_establecimiento_id),capacidad_camas:form.capacidad_camas===''?undefined:Number(form.capacidad_camas),servicios_json:servicesText.value.split(',').map(value=>value.trim()).filter(Boolean),activo:Boolean(form.activo)});editingId.value?await actualizarEstablecimiento(editingId.value,payload):await crearEstablecimiento(payload);formModal.value=false;notice.type='success';notice.text=`Establecimiento ${editingId.value?'actualizado':'creado'} correctamente.`;await load()}catch(error){formError.value=obtenerMensajeError(error)}finally{saving.value=false}}
async function openDetail(item){selected.value=item;detailModal.value=true;detailLoading.value=true;statistics.value={};contact.value={};const [detail,stats,contactResult]=await Promise.allSettled([consultarEstablecimiento(item.id),consultarEstadisticasEstablecimiento(item.id),consultarContactoEstablecimiento(item.id)]);if(detail.status==='fulfilled')selected.value=detail.value?.data||detail.value;if(stats.status==='fulfilled')statistics.value=stats.value?.data||stats.value||{};if(contactResult.status==='fulfilled')contact.value=contactResult.value?.data||contactResult.value||{};detailLoading.value=false}
function askToggle(item){toggleTarget.value=item}
async function toggleStatus(){saving.value=true;try{await cambiarEstadoEstablecimiento(toggleTarget.value.id);const action=toggleTarget.value.activo?'desactivado':'activado';toggleTarget.value=null;notice.type='success';notice.text=`Establecimiento ${action} correctamente.`;await load()}catch(error){showError(error)}finally{saving.value=false}}
function showError(error){notice.type='danger';notice.text=obtenerMensajeError(error)}
onMounted(async()=>{const [levelResult,typeResult]=await Promise.allSettled([listarNivelesAtencion(),listarTiposEstablecimiento()]);if(levelResult.status==='fulfilled')levels.value=array(levelResult.value);if(typeResult.status==='fulfilled')types.value=array(typeResult.value);await load()})
</script>

<style scoped>
