-size:.9rem;text-overflow:ellipsis;white-space:nowrap}.establishment-grid header p{margin:0;color:#8491a0;font-size:.65rem}.state{display:flex;align-items:center;gap:.3rem;padding:.28rem .5rem;border-radius:20px;font-size:.62rem;font-weight:700}.state i{font-size:.4rem}.state.active{background:#e7f7ef;color:#27865f}.state.inactive{background:#f0f2f4;color:#707d89}.institution-info{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem;padding:.8rem 1rem}.institution-info>span{display:flex;align-items:center;gap:.45rem}.institution-info i{color:var(--bs-primary)}.institution-info small,.institution-info strong{display:block}.institution-info small{color:#8995a3;font-size:.57rem}.institution-info strong{overflow:hidden;max-width:190px;font-size:.67rem;text-overflow:ellipsis;white-space:nowrap}.establishment-grid article>footer{display:flex;justify-content:flex-end;gap:.4rem;padding:.75rem 1rem;border-top:1px solid #e8edf1}.pagination-bar{display:flex;align-items:center;justify-content:center;gap:.8rem;padding:1rem;border-top:1px solid #e3e9ef;color:#68788a;font-size:.7rem}.modal-layer,.confirm-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:1rem;background:#071522b8;backdrop-filter:blur(5px)}.institution-modal,.detail-modal{width:min(760px,100%);max-height:94vh;overflow:auto;border-radius:1rem;background:#fff;box-shadow:0 28px 80px #0005}.institution-modal>header,.detail-modal>header{display:flex;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid #e4eaf0}.institution-modal h2,.detail-modal h2{margin:.12rem 0;font-size:1.12rem}.detail-modal header p{margin:0;color:#788698;font-size:.68rem}.institution-modal .modal-body,.detail-modal .modal-body{padding:1.25rem}.institution-modal footer,.detail-modal>footer{display:flex;justify-content:flex-end;gap:.6rem;padding:1rem 1.25rem;border-top:1px solid #e4eaf0}.section-title{margin:1.15rem 0 .7rem;padding-top:1rem;border-top:1px solid #e6ebf0;font-size:.82rem}.detai